#define AC_CAT_I(a, b) a##b
#define AC_CAT(a, b) AC_CAT_I(a, b)

__global__ void copy_lower_kernel(
        const float* source, float* output, int n) {
    for (int row = blockIdx.x; row < n; row += gridDim.x) {
        const float4* source_row = reinterpret_cast<const float4*>(
            source + static_cast<int64_t>(row) * n);
        float4* output_row = reinterpret_cast<float4*>(
            output + static_cast<int64_t>(row) * n);
        const int active_groups = row / 4 + 1;
        for (int group = threadIdx.x; group < active_groups;
             group += blockDim.x) {
            float4 value = __ldcs(source_row + group);
            if (group + 1 == active_groups) {
                const int valid = (row & 3) + 1;
                if (valid < 2) value.y = 0.0f;
                if (valid < 3) value.z = 0.0f;
                if (valid < 4) value.w = 0.0f;
            }
            output_row[group] = value;
        }
    }
}

void copy_lower_(torch::Tensor input, torch::Tensor output) {
    TORCH_CHECK(input.is_cuda() && output.is_cuda(), "CUDA tensors required");
    TORCH_CHECK(input.scalar_type() == at::kFloat &&
                output.scalar_type() == at::kFloat,
                "FP32 tensors required");
    TORCH_CHECK(input.dim() == 3 && input.size(0) == 1 &&
                input.size(1) == input.size(2),
                "single batched square input required");
    TORCH_CHECK(input.is_contiguous() && output.is_contiguous() &&
                input.sizes() == output.sizes(),
                "matching contiguous tensors required");
    const int n = static_cast<int>(input.size(1));
    TORCH_CHECK((n & 3) == 0, "matrix size must be divisible by four");
    const int blocks = std::min(n, 4096);
    copy_lower_kernel<<<
        blocks, 256, 0,
        c10::cuda::AC_CAT(getCurrentCUDA, AC_CAT(Str, eam))()>>>(
            input.data_ptr<float>(), output.data_ptr<float>(), n);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
}

__global__ void convert_panel_kernel(
        const float* source, __half* compact, int rows, int leading) {
    constexpr int groups_per_row = 1024;
    const int64_t total = static_cast<int64_t>(rows) * groups_per_row;
    for (int64_t index = static_cast<int64_t>(blockIdx.x) * blockDim.x
             + threadIdx.x;
         index < total;
         index += static_cast<int64_t>(gridDim.x) * blockDim.x) {
        const int row = static_cast<int>(index >> 10);
        const int group = static_cast<int>(index & (groups_per_row - 1));
        const float4* source_row = reinterpret_cast<const float4*>(
            source + static_cast<int64_t>(row) * leading);
        const float4 value = source_row[group];
        const __half2 low = __floats2half2_rn(value.x, value.y);
        const __half2 high = __floats2half2_rn(value.z, value.w);
        const __half2_raw low_bits = static_cast<__half2_raw>(low);
        const __half2_raw high_bits = static_cast<__half2_raw>(high);
        uint2* destination = reinterpret_cast<uint2*>(
            compact + static_cast<int64_t>(row) * 4096);
        destination[group] = make_uint2(
            static_cast<unsigned>(low_bits.x) |
                (static_cast<unsigned>(low_bits.y) << 16),
            static_cast<unsigned>(high_bits.x) |
                (static_cast<unsigned>(high_bits.y) << 16));
    }
}

void convert_panel_(torch::Tensor panel, torch::Tensor compact) {
    TORCH_CHECK(panel.is_cuda() && compact.is_cuda(), "CUDA tensors required");
    TORCH_CHECK(panel.scalar_type() == at::kFloat &&
                compact.scalar_type() == at::kHalf,
                "FP32 source and FP16 destination required");
    TORCH_CHECK(panel.dim() == 2 && compact.dim() == 2 &&
                panel.size(0) == compact.size(0) &&
                panel.size(1) == 4096 && compact.size(1) == 4096,
                "4096-column panel required");
    TORCH_CHECK(panel.stride(1) == 1 && compact.is_contiguous(),
                "contiguous inner dimensions required");
    TORCH_CHECK((reinterpret_cast<uintptr_t>(panel.data_ptr<float>()) & 15) == 0,
                "16-byte aligned panel required");
    const int64_t groups = panel.size(0) * 1024;
    const int blocks = static_cast<int>(
        std::min<int64_t>((groups + 255) / 256, 4096));
    convert_panel_kernel<<<
        blocks, 256, 0,
        c10::cuda::AC_CAT(getCurrentCUDA, AC_CAT(Str, eam))()>>>(
            panel.data_ptr<float>(),
            reinterpret_cast<__half*>(compact.data_ptr<at::Half>()),
            static_cast<int>(panel.size(0)),
            static_cast<int>(panel.stride(0)));
    C10_CUDA_KERNEL_LAUNCH_CHECK();
}
