@dsl_user_op
def _triangular_coordinate(self, index, *, loc=None, ip=None):
    root = cutlass.Float32(cute.math.sqrt(cutlass.Float32(index * 8 + 1)))
    row = ((root - 1.0) * 0.5).to(cutlass.Int32)
    base = row * (row + 1) // 2
    row = row - (base > index).to(cutlass.Int32)
    base = row * (row + 1) // 2
    row = row + (base + row + 1 <= index).to(cutlass.Int32)
    base = row * (row + 1) // 2
    return row, index - base, cutlass.Int32(0)


cutlass_utils.StaticPersistentTileScheduler._get_cluster_work_idx_with_fastdivmod = (
    _triangular_coordinate
)


class _TriangularGemm(_AlphaBetaGemm):
    @staticmethod
    def _compute_grid(output, tile, cluster, max_clusters):
        rows = cute.ceil_div(output.shape[0], tile[0] * 2)
        total = rows * (rows + 1) // 2
        params = cutlass_utils.PersistentTileSchedulerParams(
            (total * 2, 1, 1), (2, 1, 1)
        )
        grid = cutlass_utils.StaticPersistentTileScheduler.get_grid_shape(
            params, max_clusters
        )
        return params, grid


@cute.jit
def _rankk_host(
    operation: cutlass.Constexpr,
    panel_pointer: cute.Pointer,
    output_pointer: cute.Pointer,
    n: cutlass.Int32,
    k: cutlass.Int32,
    leading_output: cutlass.Int32,
    queue: _Queue,
):
    panel = cute.make_tensor(
        panel_pointer,
        cute.make_layout((n, k, 1), stride=(k, 1, n * k)),
    )
    output = cute.make_tensor(
        output_pointer,
        cute.make_layout(
            (n, n, 1), stride=(leading_output, 1, n * leading_output)
        ),
    )
    operation(
        panel,
        panel,
        output,
        output,
        cutlass.Float32(-1.0),
        cutlass.Float32(1.0),
        74,
        queue,
    )


